-- ----------------------------
-- Table structure for ai_ab_test
-- ----------------------------
DROP TABLE IF EXISTS `ai_ab_test`;
CREATE TABLE `ai_ab_test`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `test_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试名称',
  `description` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '测试描述',
  `model_a_id` bigint(20) NOT NULL COMMENT '模型A的ID',
  `model_b_id` bigint(20) NOT NULL COMMENT '模型B的ID',
  `test_questions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试问题列表（JSON数组）',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'PENDING' COMMENT '状态：PENDING/RUNNING/COMPLETED',
  `result_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '结果摘要（JSON）',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI A/B 测试' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for ai_ab_test_result
-- ----------------------------
DROP TABLE IF EXISTS `ai_ab_test_result`;
CREATE TABLE `ai_ab_test_result`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户ID',
  `test_id` bigint(20) NOT NULL COMMENT '测试ID',
  `question` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '测试问题',
  `model_id` bigint(20) NOT NULL COMMENT '模型ID',
  `model_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型名称',
  `response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '模型回答',
  `token_usage` int(11) NULL DEFAULT NULL COMMENT 'Token 用量',
  `latency_ms` int(11) NULL DEFAULT NULL COMMENT '响应延迟（毫秒）',
  `score` int(11) NULL DEFAULT NULL COMMENT '人工评分（1-5）',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_test_id`(`test_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI A/B 测试结果' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for ai_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_config`;
CREATE TABLE `ai_config`  (
  `config_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置分组: sql_safety/vector_store/web_search/flow/knowledge_graph',
  `config_value` json NULL COMMENT '配置值(分组内字段JSON)',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`config_group`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI运行参数配置(全局, 页面化替代nexus.ai yml运行参数)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_config
-- ----------------------------

-- ----------------------------
-- Table structure for ai_decision_action
-- ----------------------------
DROP TABLE IF EXISTS `ai_decision_action`;
CREATE TABLE `ai_decision_action`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `run_id` bigint(20) NOT NULL COMMENT '决策运行ID',
  `action_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作类型',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作标题',
  `display_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '展示理由',
  `target_biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标业务类型',
  `target_biz_id` bigint(20) NULL DEFAULT NULL COMMENT '目标业务ID',
  `target_biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标业务编号',
  `payload_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '白名单动作参数JSON',
  `purchase_payload_version` tinyint(4) NULL DEFAULT NULL COMMENT '采购动作载荷合同版本；NULL为旧合同，必须与run和冻结载荷校验',
  `risk_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作风险等级',
  `approval_required` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Y' COMMENT '是否需要审批',
  `approval_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批状态',
  `execution_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行状态',
  `permission_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '业务权限码',
  `executor_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '执行器编码',
  `sequence_no` int(11) NOT NULL DEFAULT 0 COMMENT '执行顺序',
  `dependency_ids_json` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '依赖动作ID JSON',
  `idempotency_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '幂等键',
  `approved_by` bigint(20) NULL DEFAULT NULL COMMENT '审批人',
  `approved_at` datetime(0) NULL DEFAULT NULL COMMENT '审批时间',
  `approval_comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批意见',
  `result_biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '结果业务类型',
  `result_biz_id` bigint(20) NULL DEFAULT NULL COMMENT '结果业务ID',
  `result_biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '结果业务编号',
  `result_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '执行结果JSON',
  `retry_count` int(11) NOT NULL DEFAULT 0 COMMENT '重试次数',
  `last_error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后错误码',
  `last_error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后脱敏错误',
  `started_at` datetime(0) NULL DEFAULT NULL COMMENT '执行开始时间',
  `finished_at` datetime(0) NULL DEFAULT NULL COMMENT '执行完成时间',
  `version` int(11) NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_decision_action_idempotency`(`tenant_id`, `idempotency_key`) USING BTREE,
  INDEX `idx_decision_action_run`(`run_id`, `sequence_no`) USING BTREE,
  INDEX `idx_decision_action_approval`(`tenant_id`, `approval_status`) USING BTREE,
  INDEX `idx_decision_action_execution`(`tenant_id`, `execution_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI工业决策动作' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_decision_action
-- ----------------------------

-- ----------------------------
-- Table structure for ai_decision_evidence
-- ----------------------------
DROP TABLE IF EXISTS `ai_decision_evidence`;
CREATE TABLE `ai_decision_evidence`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `run_id` bigint(20) NOT NULL COMMENT '决策运行ID',
  `evidence_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行内证据键',
  `source_domain` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ERP/MES/IOT/RAG/RULE/DERIVED',
  `source_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型',
  `source_id` bigint(20) NULL DEFAULT NULL COMMENT '来源ID',
  `source_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源编号',
  `source_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源名称',
  `metric_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标编码',
  `metric_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标名称',
  `value_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '值类型',
  `metric_value` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '指标展示值',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位',
  `observed_at` datetime(0) NULL DEFAULT NULL COMMENT '观察时间',
  `data_version` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数据版本',
  `confidence` decimal(5, 4) NULL DEFAULT NULL COMMENT '置信度',
  `verifiable` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Y' COMMENT '是否可验证',
  `normative` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'N' COMMENT '是否规范性证据',
  `derived_from_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '派生来源证据键JSON',
  `display_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '前端业务跳转路径',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_decision_evidence`(`run_id`, `evidence_key`) USING BTREE,
  INDEX `idx_decision_evidence_source`(`tenant_id`, `source_type`, `source_id`) USING BTREE,
  INDEX `idx_decision_evidence_run`(`run_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI工业决策证据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_decision_evidence
-- ----------------------------

-- ----------------------------
-- Table structure for ai_decision_run
-- ----------------------------
DROP TABLE IF EXISTS `ai_decision_run`;
CREATE TABLE `ai_decision_run`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `scene_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场景编码',
  `biz_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) NULL DEFAULT NULL COMMENT '根业务ID',
  `biz_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '根业务编号',
  `parent_run_id` bigint(20) NULL DEFAULT NULL COMMENT '父运行ID',
  `superseded_by_run_id` bigint(20) NULL DEFAULT NULL COMMENT '替代运行ID',
  `trigger_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发类型',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行状态',
  `decision_contract_version` tinyint(4) NULL DEFAULT NULL COMMENT '决策合同版本；NULL为旧合同，只有可信新版路径显式写2',
  `risk_score` decimal(8, 2) NULL DEFAULT NULL COMMENT '风险分数',
  `risk_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '风险等级',
  `confidence_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '置信度等级',
  `recommended_scenario_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '推荐方案编码',
  `input_snapshot_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输入快照JSON',
  `input_snapshot_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '输入快照SHA-256',
  `snapshot_time` datetime(0) NULL DEFAULT NULL COMMENT '快照时间',
  `valid_until` datetime(0) NULL DEFAULT NULL COMMENT '审批有效截止时间',
  `score_config_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '评分配置快照',
  `scenario_result_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '场景推演结果',
  `narrative_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '决策说明JSON',
  `result_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '完整决策结果JSON',
  `outcome_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '执行后结果JSON',
  `approval_context_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '可信审批执行人权限快照（禁止从Flow输入恢复）',
  `summary_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'MODEL/TEMPLATE_FALLBACK',
  `model_id` bigint(20) NULL DEFAULT NULL COMMENT '模型ID',
  `model_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型名称快照',
  `prompt_version` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Prompt版本',
  `input_tokens` int(11) NULL DEFAULT NULL COMMENT '输入Token',
  `output_tokens` int(11) NULL DEFAULT NULL COMMENT '输出Token',
  `estimated_cost` decimal(18, 6) NULL DEFAULT NULL COMMENT '估算成本',
  `analysis_flow_instance_id` bigint(20) NULL DEFAULT NULL COMMENT '分析Flow实例ID',
  `execution_flow_instance_id` bigint(20) NULL DEFAULT NULL COMMENT '执行Flow实例ID',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '错误码',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '脱敏错误信息',
  `started_at` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `analysis_finished_at` datetime(0) NULL DEFAULT NULL COMMENT '分析完成时间',
  `finished_at` datetime(0) NULL DEFAULT NULL COMMENT '完成时间',
  `version` int(11) NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标志',
  `attr1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段4',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_decision_tenant_scene_status`(`tenant_id`, `scene_code`, `status`) USING BTREE,
  INDEX `idx_decision_biz`(`tenant_id`, `biz_type`, `biz_id`) USING BTREE,
  INDEX `idx_decision_create_time`(`tenant_id`, `create_time`) USING BTREE,
  INDEX `idx_decision_parent`(`parent_run_id`) USING BTREE,
  INDEX `idx_decision_analysis_flow`(`analysis_flow_instance_id`) USING BTREE,
  INDEX `idx_decision_execution_flow`(`execution_flow_instance_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI工业决策运行' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_decision_run
-- ----------------------------

-- ----------------------------
-- Table structure for ai_engineering_artifact
-- ----------------------------
DROP TABLE IF EXISTS `ai_engineering_artifact`;
CREATE TABLE `ai_engineering_artifact`  (
  `artifact_id` bigint(20) NOT NULL COMMENT '产物编号',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '产物所有者',
  `task_id` bigint(20) NOT NULL COMMENT '所属任务',
  `attempt` int(11) NOT NULL COMMENT '所属尝试编号',
  `artifact_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产物类型',
  `group_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '模型材质组',
  `relative_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '组内相对路径，区分大小写',
  `service` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '显式私有存储配置键',
  `oss_id` bigint(20) NULL DEFAULT NULL COMMENT '内部私有对象编号',
  `object_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '服务端对象键，不对外输出',
  `sha256` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务端复核内容摘要',
  `size` bigint(20) NOT NULL COMMENT '真实字节数',
  `mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '验证后媒体类型',
  `original_filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '安全显示文件名',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RESERVED' COMMENT '预留、确认或待清理状态',
  `cleanup_generation` bigint(20) NOT NULL DEFAULT 0 COMMENT '清理租约CAS代数，旧进程不得覆盖新清理者',
  `cleanup_expires_at` datetime(0) NULL DEFAULT NULL COMMENT '清理租约到期或失败后重试时间，过期CLEANING可恢复',
  `validation_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '服务端格式解析摘要',
  `created_at` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建审计时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '修改审计时间',
  PRIMARY KEY (`artifact_id`) USING BTREE,
  UNIQUE INDEX `uk_engineering_artifact_path`(`tenant_id`, `task_id`, `attempt`, `artifact_type`, `relative_path`) USING BTREE,
  INDEX `idx_engineering_artifact_owner`(`tenant_id`, `user_id`, `task_id`, `status`) USING BTREE,
  INDEX `idx_engineering_artifact_cleanup`(`status`, `cleanup_expires_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI工程私有产物' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_engineering_artifact
-- ----------------------------

-- ----------------------------
-- Table structure for ai_engineering_device
-- ----------------------------
DROP TABLE IF EXISTS `ai_engineering_device`;
CREATE TABLE `ai_engineering_device`  (
  `device_id` bigint(20) NOT NULL COMMENT '设备编号',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '000000' COMMENT '租户编号，保留前导零',
  `user_id` bigint(20) NOT NULL COMMENT '所有者用户编号',
  `device_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '设备显示名称',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '设备状态',
  `access_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '访问凭证摘要',
  `refresh_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '刷新凭证摘要',
  `generation` bigint(20) NOT NULL DEFAULT 1 COMMENT '凭证代数',
  `access_expires_at` datetime(0) NULL DEFAULT NULL COMMENT '访问凭证到期时间',
  `refresh_expires_at` datetime(0) NULL DEFAULT NULL COMMENT '刷新凭证到期时间',
  `credential_fingerprint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '配对时认证状态内部摘要',
  `capabilities` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '设备实际能力与版本',
  `allowed_capabilities` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '配对允许能力集合',
  `last_heartbeat` datetime(0) NULL DEFAULT NULL COMMENT '最近心跳时间',
  `busy_task_id` bigint(20) NULL DEFAULT NULL COMMENT '正在执行的任务',
  `created_at` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建审计时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '修改审计时间',
  PRIMARY KEY (`device_id`) USING BTREE,
  UNIQUE INDEX `uk_engineering_device_access`(`access_hash`) USING BTREE,
  UNIQUE INDEX `uk_engineering_device_refresh`(`refresh_hash`) USING BTREE,
  INDEX `idx_engineering_device_owner`(`tenant_id`, `user_id`, `status`, `last_heartbeat`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI工程设备' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_engineering_device
-- ----------------------------

-- ----------------------------
-- Table structure for ai_engineering_task
-- ----------------------------
DROP TABLE IF EXISTS `ai_engineering_task`;
CREATE TABLE `ai_engineering_task`  (
  `task_id` bigint(20) NOT NULL COMMENT '任务编号',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT '000000' COMMENT '租户编号',
  `user_id` bigint(20) NOT NULL COMMENT '任务所有者',
  `device_id` bigint(20) NOT NULL COMMENT '指定执行设备',
  `session_id` bigint(20) NULL DEFAULT NULL COMMENT '关联会话编号',
  `request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '服务端聊天请求标识',
  `parent_task_id` bigint(20) NULL DEFAULT NULL COMMENT '原任务编号',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '受控动作',
  `idempotency_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '用户作用域幂等键',
  `request_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范请求摘要',
  `request_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '有界结构化请求',
  `state` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务状态',
  `stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前阶段',
  `attempt` int(11) NOT NULL DEFAULT 0 COMMENT '领取尝试编号',
  `revision` bigint(20) NOT NULL DEFAULT 0 COMMENT '比较交换修订号',
  `lease_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租约凭证摘要',
  `lease_expires_at` datetime(0) NULL DEFAULT NULL COMMENT '租约到期时间',
  `deadline_at` datetime(0) NULL DEFAULT NULL COMMENT '运行截止时间',
  `waiting_expires_at` datetime(0) NULL DEFAULT NULL COMMENT '等待设备截止时间',
  `cancel_requested` tinyint(1) NOT NULL DEFAULT 0 COMMENT '运行取消请求',
  `step_journal` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '有界步骤回执日志',
  `reserved_bytes` bigint(20) NOT NULL DEFAULT 0 COMMENT '已确认及预留字节总量',
  `reserved_files` int(11) NOT NULL DEFAULT 0 COMMENT '已确认及预留文件数量',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '安全错误类别',
  `error_message` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '中文安全错误摘要',
  `created_at` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(0) NULL DEFAULT NULL COMMENT '修改时间',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建用户',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建审计时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '修改用户',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '修改审计时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  UNIQUE INDEX `uk_engineering_task_owner`(`tenant_id`, `user_id`, `idempotency_key`) USING BTREE,
  INDEX `idx_engineering_task_device`(`tenant_id`, `user_id`, `device_id`, `state`) USING BTREE,
  INDEX `idx_engineering_task_expiry`(`state`, `lease_expires_at`, `waiting_expires_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI工程任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_engineering_task
-- ----------------------------

-- ----------------------------
-- Table structure for ai_flow
-- ----------------------------
DROP TABLE IF EXISTS `ai_flow`;
CREATE TABLE `ai_flow`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `flow_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程名称',
  `flow_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程标识(唯一, 定时/Webhook 引用)',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '状态: DRAFT/PUBLISHED/OFFLINE',
  `version` int(11) NOT NULL DEFAULT 1 COMMENT '版本号(每次发布+1)',
  `config_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '画布配置(JSON: nodes+edges)',
  `trigger_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'MANUAL' COMMENT '触发方式: MANUAL/SCHEDULE (逗号分隔可多选)',
  `cron_expr` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '定时 Cron 表达式',
  `max_retry` int(11) NOT NULL DEFAULT 1 COMMENT '节点失败最大重试次数',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段4',
  `webhook_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Webhook访问令牌(空=不校验, flowKey本身即令牌)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_flow_key`(`flow_key`) USING BTREE,
  INDEX `idx_tenant_status`(`tenant_id`, `status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI 流程定义' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_flow
-- ----------------------------

-- ----------------------------
-- Table structure for ai_flow_instance
-- ----------------------------
DROP TABLE IF EXISTS `ai_flow_instance`;
CREATE TABLE `ai_flow_instance`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID',
  `flow_version` int(11) NOT NULL DEFAULT 1 COMMENT '运行时的流程版本',
  `trigger_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '触发方式: MANUAL/SCHEDULE',
  `trigger_by` bigint(20) NULL DEFAULT NULL COMMENT '触发人(定时任务=流程创建人, 用于SSE通知)',
  `input_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输入(JSON)',
  `output_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输出(JSON, 末节点输出)',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUNNING' COMMENT '状态: RUNNING/SUCCEEDED/FAILED/STOPPED',
  `error_msg` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '错误信息',
  `duration_ms` bigint(20) NULL DEFAULT NULL COMMENT '总耗时(毫秒)',
  `node_total` int(11) NULL DEFAULT 0 COMMENT '节点总数',
  `node_success` int(11) NULL DEFAULT 0 COMMENT '成功节点数',
  `node_failed` int(11) NULL DEFAULT 0 COMMENT '失败节点数',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段4',
  `config_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '启动时画布配置快照(续跑用)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_flow_id`(`flow_id`, `id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI 流程运行实例' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_flow_instance
-- ----------------------------

-- ----------------------------
-- Table structure for ai_flow_node_run
-- ----------------------------
DROP TABLE IF EXISTS `ai_flow_node_run`;
CREATE TABLE `ai_flow_node_run`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '000000' COMMENT '租户编号',
  `instance_id` bigint(20) NOT NULL COMMENT '实例ID',
  `flow_id` bigint(20) NOT NULL COMMENT '流程ID(冗余, 便于查询)',
  `node_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '画布节点ID(如 node_1)',
  `node_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '节点名称',
  `node_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点类型: LLM/AGENT/RAG/IF/CODE',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态: PENDING/RUNNING/SUCCEEDED/FAILED/SKIPPED',
  `input_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输入(JSON, 渲染后的最终入参)',
  `output_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '输出(JSON)',
  `error_msg` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '错误信息',
  `retry_count` int(11) NOT NULL DEFAULT 0 COMMENT '已重试次数',
  `duration_ms` bigint(20) NULL DEFAULT NULL COMMENT '耗时(毫秒)',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint(20) NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  `attr1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段1',
  `attr2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段2',
  `attr3` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段3',
  `attr4` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段4',
  `batch_index` int(11) NOT NULL DEFAULT 0 COMMENT '循环批次索引(非循环执行=0)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_instance_id`(`instance_id`) USING BTREE,
  INDEX `idx_flow_id`(`flow_id`) USING BTREE,
  INDEX `idx_instance_batch`(`instance_id`, `batch_index`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI 流程节点运行记录' ROW_FORMAT = Dynamic;

-- ----------------------------
