-- ----------------------------
-- Table structure for rpt_acl
-- ----------------------------
DROP TABLE IF EXISTS `rpt_acl`;
CREATE TABLE `rpt_acl`  (
  `acl_id` bigint(20) NOT NULL COMMENT '资源授权ID',
  `resource_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资源类型',
  `resource_id` bigint(20) NOT NULL COMMENT '被授权报表资源ID',
  `subject_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '授权主体类型（用户、角色或部门）',
  `subject_id` bigint(20) NOT NULL COMMENT '被授权用户、角色或部门ID',
  `action` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资源授权操作（查看、编辑、发布、运行、导出、授权或管理）',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建人部门ID',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人用户ID',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`acl_id`) USING BTREE,
  UNIQUE INDEX `uk_report_acl`(`tenant_id`, `resource_type`, `resource_id`, `subject_type`, `subject_id`, `action`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表资源访问授权' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rpt_acl
-- ----------------------------

-- ----------------------------
-- Table structure for rpt_artifact_manifest
-- ----------------------------
DROP TABLE IF EXISTS `rpt_artifact_manifest`;
CREATE TABLE `rpt_artifact_manifest`  (
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `store_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有存储实例标识',
  `reference` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有文件逻辑引用',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有文件生命周期状态',
  `reserved_bytes` bigint(20) NOT NULL DEFAULT 0 COMMENT '写入预留容量（字节）',
  `content_length` bigint(20) NOT NULL DEFAULT 0 COMMENT '已提交文件大小（字节）',
  `checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内容SHA-256校验和',
  `lease_owner` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '当前执行租约持有者',
  `staging_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '尚未提交文件的暂存路径',
  `lease_until` datetime(0) NOT NULL COMMENT '当前执行租约到期时间',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`tenant_id`, `store_id`, `reference`) USING BTREE,
  INDEX `idx_rpt_manifest_recovery`(`store_id`, `state`, `update_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表私有文件生命周期清单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for rpt_asset
-- ----------------------------
DROP TABLE IF EXISTS `rpt_asset`;
CREATE TABLE `rpt_asset`  (
  `asset_id` bigint(20) NOT NULL COMMENT '私有图片资源ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有图片资源唯一编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有图片资源名称',
  `definition_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有图片资源草稿定义JSON',
  `revision` bigint(20) NOT NULL DEFAULT 1 COMMENT '草稿修订号（乐观锁）',
  `published_version_id` bigint(20) NULL DEFAULT NULL COMMENT '当前发布版本ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '私有图片资源生命周期状态',
  `create_dept` bigint(20) NOT NULL COMMENT '创建人部门ID',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`asset_id`) USING BTREE,
  UNIQUE INDEX `uk_rpt_asset_code`(`tenant_id`, `code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表私有图片资源定义' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rpt_asset
-- ----------------------------

-- ----------------------------
-- Table structure for rpt_asset_version
-- ----------------------------
DROP TABLE IF EXISTS `rpt_asset_version`;
CREATE TABLE `rpt_asset_version`  (
  `version_id` bigint(20) NOT NULL COMMENT '私有图片资源发布版本ID',
  `asset_id` bigint(20) NOT NULL COMMENT '私有图片资源ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `version_no` int(11) NOT NULL COMMENT '资源内递增版本号',
  `definition_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '不可变私有图片资源定义JSON',
  `dependency_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '固定依赖版本与范围指纹JSON',
  `checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容SHA-256校验和',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`version_id`) USING BTREE,
  UNIQUE INDEX `uk_rpt_asset_version_number`(`tenant_id`, `asset_id`, `version_no`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表私有图片资源版本' ROW_FORMAT = Dynamic;

