  `catalog_id` bigint(20) NULL DEFAULT NULL COMMENT '所属报表目录ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报表唯一编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报表名称',
  `kind` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报表类型（表格、单据或交叉报表）',
  `draft_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报表DSL草稿JSON',
  `draft_revision` bigint(20) NOT NULL DEFAULT 1 COMMENT '草稿修订号（乐观锁）',
  `published_version_id` bigint(20) NULL DEFAULT NULL COMMENT '当前发布版本ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '报表生命周期状态',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建人部门ID',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人用户ID',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`report_id`) USING BTREE,
  UNIQUE INDEX `uk_report_code`(`tenant_id`, `code`) USING BTREE,
  INDEX `idx_report_definition_catalog`(`tenant_id`, `catalog_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表定义与草稿' ROW_FORMAT = Dynamic;

