-- ----------------------------
-- Table structure for rpt_delivery
-- ----------------------------
DROP TABLE IF EXISTS `rpt_delivery`;
CREATE TABLE `rpt_delivery`  (
  `delivery_id` bigint(20) NOT NULL COMMENT '私有交付ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `execution_id` bigint(20) NOT NULL COMMENT '订阅执行ID',
  `subscription_id` bigint(20) NOT NULL COMMENT '报表订阅ID',
  `definition_version_id` bigint(20) NOT NULL COMMENT '固定订阅定义版本ID',
  `recipient_id` bigint(20) NOT NULL COMMENT '接收人用户ID',
  `job_id` bigint(20) NOT NULL COMMENT '导出任务ID',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PREPARING' COMMENT '接收人私有交付状态',
  `notification_state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DISABLED' COMMENT '交付通知状态',
  `notification_attempts` int(11) NOT NULL DEFAULT 0 COMMENT '已尝试通知次数',
  `expires_at` datetime(6) NOT NULL COMMENT '交付文件有效期截止时间',
  `claimed_at` datetime(6) NULL DEFAULT NULL COMMENT '接收人领取时间',
  `error_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受控错误码',
  PRIMARY KEY (`delivery_id`) USING BTREE,
  UNIQUE INDEX `uk_rpt_delivery_execution`(`tenant_id`, `execution_id`) USING BTREE,
  INDEX `idx_rpt_delivery_recipient`(`tenant_id`, `recipient_id`, `state`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表接收人私有交付' ROW_FORMAT = Dynamic;

