-- Table structure for rpt_dispatch_gate
-- ----------------------------
DROP TABLE IF EXISTS `rpt_dispatch_gate`;
CREATE TABLE `rpt_dispatch_gate`  (
  `scope_key` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公平调度作用域标识',
  `last_claim` datetime(0) NULL DEFAULT NULL COMMENT '最近一次领取任务的调度标记',
  PRIMARY KEY (`scope_key`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表公平调度领取控制' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for rpt_export_job
-- ----------------------------
DROP TABLE IF EXISTS `rpt_export_job`;
CREATE TABLE `rpt_export_job`  (
  `job_id` bigint(20) NOT NULL COMMENT '导出任务ID',
  `actor_id` bigint(20) NOT NULL COMMENT '操作用户ID',
  `run_id` bigint(20) NOT NULL COMMENT '报表运行ID',
  `format` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '导出文件格式',
  `idempotency_key` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '请求幂等键',
  `request_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规范化请求参数指纹',
  `state` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '导出任务状态',
  `execution_phase` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'QUEUED' COMMENT '导出任务执行阶段',
  `processed_rows` bigint(20) NOT NULL DEFAULT 0 COMMENT '已处理数据行数',
  `total_rows` bigint(20) NULL DEFAULT NULL COMMENT '预计处理总行数',
  `retry_round` int(11) NOT NULL DEFAULT 0 COMMENT '任务重试轮次',
  `last_heartbeat` datetime(0) NULL DEFAULT NULL COMMENT '执行器最近心跳时间',
  `attempts` int(11) NOT NULL DEFAULT 0 COMMENT '已尝试执行次数',
  `lease_owner` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前执行租约持有者',
  `lease_until` datetime(0) NULL DEFAULT NULL COMMENT '当前执行租约到期时间',
  `cancel_requested` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否请求取消任务',
  `file_ref` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '私有导出文件逻辑引用',
  `file_size` bigint(20) NULL DEFAULT NULL COMMENT '导出文件大小（字节）',
  `expires_at` datetime(0) NOT NULL COMMENT '导出文件有效期截止时间',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受控错误码',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建人部门ID',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人用户ID',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`job_id`) USING BTREE,
  UNIQUE INDEX `uk_report_export_request`(`tenant_id`, `actor_id`, `idempotency_key`) USING BTREE,
  INDEX `idx_report_export_claim`(`state`, `lease_until`) USING BTREE,
  INDEX `idx_report_export_owner`(`tenant_id`, `actor_id`, `create_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表异步导出任务' ROW_FORMAT = Dynamic;

