-- ----------------------------
DROP TABLE IF EXISTS `rpt_query_dataset_binding`;
CREATE TABLE `rpt_query_dataset_binding`  (
  `dataset_version_id` bigint(20) NOT NULL COMMENT '固定数据集版本ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `query_version_id` bigint(20) NOT NULL COMMENT '固定受控查询版本ID',
  `catalog_version` int(11) NOT NULL COMMENT '批准的逻辑目录版本',
  `query_checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '受控查询定义SHA-256校验和',
  `catalog_checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '逻辑目录内容SHA-256校验和',
  PRIMARY KEY (`dataset_version_id`) USING BTREE,
  INDEX `idx_rpt_query_dataset_tenant`(`tenant_id`, `query_version_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '受控查询与数据集版本绑定' ROW_FORMAT = Dynamic;

