-- ----------------------------
-- Table structure for rpt_query_definition
-- ----------------------------
DROP TABLE IF EXISTS `rpt_query_definition`;
CREATE TABLE `rpt_query_definition`  (
  `query_id` bigint(20) NOT NULL COMMENT '受控查询定义ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '受控查询唯一编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '受控查询名称',
  `definition_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '受控查询草稿定义JSON',
  `revision` bigint(20) NOT NULL DEFAULT 1 COMMENT '草稿修订号（乐观锁）',
  `published_version_id` bigint(20) NULL DEFAULT NULL COMMENT '当前发布版本ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'DRAFT' COMMENT '受控查询生命周期状态',
  `create_dept` bigint(20) NOT NULL COMMENT '创建人部门ID',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`query_id`) USING BTREE,
  UNIQUE INDEX `uk_rpt_query_definition_code`(`tenant_id`, `code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表受控查询定义' ROW_FORMAT = Dynamic;

