  `version_no` int(11) NOT NULL COMMENT '资源内递增版本号',
  `definition_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '不可变受控查询定义JSON',
  `dependency_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '固定依赖版本与范围指纹JSON',
  `checksum` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '内容SHA-256校验和',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`version_id`) USING BTREE,
  UNIQUE INDEX `uk_rpt_query_version_number`(`tenant_id`, `query_id`, `version_no`) USING BTREE
