  `version_id` bigint(20) NOT NULL COMMENT '不可变版本ID',
  `artifact_ref` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '私有文件逻辑引用',
  PRIMARY KEY (`tenant_id`, `resource_type`, `version_id`) USING BTREE,
  INDEX `idx_rpt_resource_artifact`(`tenant_id`, `artifact_ref`) USING BTREE
