-- ----------------------------
-- Table structure for rpt_run
-- ----------------------------
DROP TABLE IF EXISTS `rpt_run`;
CREATE TABLE `rpt_run`  (
  `run_id` bigint(20) NOT NULL COMMENT '报表运行ID',
  `actor_id` bigint(20) NOT NULL COMMENT '操作用户ID',
  `report_id` bigint(20) NOT NULL COMMENT '报表定义ID',
  `version_id` bigint(20) NOT NULL COMMENT '不可变版本ID',
  `mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报表运行模式',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报表运行状态',
  `parameters_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '固定运行参数JSON',
  `scope_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '服务端权限与业务范围指纹',
  `snapshot_ref` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '私有数据快照逻辑引用',
  `plan_ref` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '私有渲染计划逻辑引用',
  `row_count` bigint(20) NOT NULL DEFAULT 0 COMMENT '数据快照总行数',
  `data_time` datetime(0) NOT NULL COMMENT '业务数据快照时间',
  `expires_at` datetime(0) NOT NULL COMMENT '运行快照有效期截止时间',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受控错误码',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `create_dept` bigint(20) NULL DEFAULT NULL COMMENT '创建人部门ID',
  `create_by` bigint(20) NOT NULL COMMENT '创建人用户ID',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint(20) NULL DEFAULT NULL COMMENT '更新人用户ID',
  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`run_id`) USING BTREE,
  INDEX `idx_report_run_owner`(`tenant_id`, `actor_id`, `create_time`) USING BTREE,
  INDEX `idx_report_run_expiry`(`expires_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表运行记录与私有快照' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of rpt_run
-- ----------------------------

