  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `subscription_id` bigint(20) NOT NULL COMMENT '报表订阅ID',
  `scheduled_key` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订阅触发幂等键',
  `definition_version_id` bigint(20) NOT NULL COMMENT '固定订阅定义版本ID',
  `scheduled_instant` datetime(6) NOT NULL COMMENT '本次触发计划时间',
  `event_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订阅触发事件类型',
  PRIMARY KEY (`tenant_id`, `subscription_id`, `scheduled_key`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表订阅触发去重记录' ROW_FORMAT = Dynamic;

