-- Records of rpt_subscription_occurrence
-- ----------------------------

-- ----------------------------
-- Table structure for rpt_subscription_run
-- ----------------------------
DROP TABLE IF EXISTS `rpt_subscription_run`;
CREATE TABLE `rpt_subscription_run`  (
  `execution_id` bigint(20) NOT NULL COMMENT '订阅执行ID',
  `tenant_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '租户隔离标识',
  `subscription_id` bigint(20) NOT NULL COMMENT '报表订阅ID',
  `definition_version_id` bigint(20) NOT NULL COMMENT '固定订阅定义版本ID',
  `scheduled_key` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订阅触发幂等键',
  `scheduled_instant` datetime(6) NOT NULL COMMENT '本次触发计划时间',
  `event_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订阅触发事件类型',
  `recipient_id` bigint(20) NOT NULL COMMENT '接收人用户ID',
  `job_id` bigint(20) NULL DEFAULT NULL COMMENT '导出任务ID',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订阅执行与重试状态',
  `attempts` int(11) NOT NULL DEFAULT 0 COMMENT '已尝试执行次数',
  `next_retry_at` datetime(6) NULL DEFAULT NULL COMMENT '下一次允许重试时间',
  `error_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受控错误码',
  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`execution_id`) USING BTREE,
  UNIQUE INDEX `uk_rpt_subscription_occurrence`(`tenant_id`, `subscription_id`, `scheduled_key`, `recipient_id`) USING BTREE,
  INDEX `idx_rpt_subscription_recipient`(`tenant_id`, `recipient_id`, `state`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表订阅执行与重试记录' ROW_FORMAT = Dynamic;

