  `next_at` datetime(6) NOT NULL COMMENT '下一次计划触发时间',
  `last_error` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近一次调度错误码',
  PRIMARY KEY (`tenant_id`, `subscription_id`) USING BTREE,
  INDEX `idx_rpt_subscription_due`(`enabled`, `next_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '报表订阅调度状态' ROW_FORMAT = Dynamic;

