  INDEX `idx_trigger_at`(`trigger_at`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'DashBoard_Retry' ROW_FORMAT = Dynamic;

